describe('File Upload - File Size Validation', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully upload a file smaller than 5MB', () => {
    // Setup: Create a small dummy file (e.g., 1MB)
    const smallFileContent = new Uint8Array(1 * 1024 * 1024);
    const smallFile = new File([smallFileContent], 'small-document.pdf', {
      type: 'application/pdf',
      lastModified: Date.now(),
    });

    // Intercept the upload API call
    cy.intercept('POST', '/api/upload').as('uploadFile');

    // Upload the small file
    cy.get('[data-testid="file-input"]').selectFile(smallFile);

    // Verify file name and size are displayed
    cy.get('[data-testid="file-name-display"]').should('contain', 'small-document.pdf');
    cy.get('[data-testid="file-size-display"]').should('contain', '1MB');

    // Submit the form
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@uploadFile').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');
    cy.get('[data-testid="error-message"]').should('not.exist');
  });

  it('should reject files larger than 5MB and display error message', () => {
    // Setup: Create a large dummy file (e.g., 6MB)
    const largeFileContent = new Uint8Array(6 * 1024 * 1024);
    const largeFile = new File([largeFileContent], 'large-document.pdf', {
      type: 'application/pdf',
      lastModified: Date.now(),
    });

    // Intercept the upload API call (it should not be called)
    cy.intercept('POST', '/api/upload').as('uploadFile');

    // Attempt to upload the large file
    cy.get('[data-testid="file-input"]').selectFile(largeFile);

    // Verify file name and size are displayed
    cy.get('[data-testid="file-name-display"]').should('contain', 'large-document.pdf');
    cy.get('[data-testid="file-size-display"]').should('contain', '6MB');

    // Attempt to submit the form
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload API was NOT called
    cy.get('@uploadFile.all').should('have.length', 0);

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'File size exceeds 5MB limit');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify file input is still visible and selectable
    cy.get('[data-testid="file-input"]').should('be.visible');
  });
});
